  "loc.gpsTracker": "🛰️ GPS-spårare",
  "loc.guide1": "Installera appen <b>”Traccar Client”</b> (App Store eller Google Play, kostnadsfri).",
  "loc.guide2": "Ange i appen under <b>Device ID</b> (enhetsidentifierare):",
  "loc.guide3": "Ange under <b>Server URL</b>:",
  "loc.guide4": "Noggrannhet <b>Medium</b>, avstånd <b>50 m</b>. Appen skickar då bara när du rör dig – inget när du står still. Har du fler fält (intervall, heartbeat), ställ in heartbeat på av eller 0.",
  "loc.guide5": "Tillåt positionsåtkomst: <b>Alltid</b> och <b>Exakt position</b> på.",
  "loc.guide6": "Slå på reglaget <b>Service / Tracking</b> och <b>låt det alltid vara på</b> – klart. Därefter styr du allt i pinn.: ”Skicka permanent” på eller av, ”Skicka en gång” och SOS. Så länge ”Skicka permanent” är av ser ingen din position och pinn. registrerar ingen rutt.",
  "loc.guideIntro": "Utan en annan app fungerar ”📍 Dela position” direkt i pinn. – men bara medan pinn. är öppet. För att positionen också kommer fram när pinn. är stängt och skärmen låst skickar den kostnadsfria appen ”Traccar Client” den direkt till pinn. (ingen Traccar-server behövs). Samma sak för iPhone och Android.",
