  "loc.setupIntro": "Telefoner behöver inget annat: alla kan dela direkt i pinn. under ”Min position”. I bakgrunden (pinn. stängt) skickar telefonen med den kostnadsfria appen ”Traccar Client” (iPhone och Android) – direkt till pinn., ingen Traccar-server behövs. Bara GPS-spårare med SIM-kort (t.ex. på ett halsband) behöver containern ”traccar”. Positionerna stannar på din NAS.",
