  "loc.traccarClientChooseSend": "Välj ”Send SOS” i ”Traccar Client” (beroende på version i appen eller genom att trycka länge på appikonen). pinn. larmar direkt alla familjemedlemmar via push – med position, adress, tid och knappar för samtal och nödnummer {regionNotrufText}. Tips: ange ditt eget mobilnummer på nödkortet.",
